type PostRouteContext = {
  params: Promise<{ id: string }>;
};

type UpdatePostBody = {
  title?: string;
  content?: string;
};

function parsePostId(rawId: string): number | null {
  const id = Number.parseInt(rawId, 10);
  return Number.isNaN(id) ? null : id;
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id: rawId } = await params;
  const id = parsePostId(rawId);

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post = {
    id,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return Response.json(post);
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id: rawId } = await params;
  const id = parsePostId(rawId);

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost = {
    id,
    title: body.title ?? `Post ${id}`,
    content: body.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return Response.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id: rawId } = await params;
  const id = parsePostId(rawId);

  if (id === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return Response.json({ message: `Post ${id} deleted successfully` });
}

